package ai.eva.android.probe;
import android.content.*;import android.os.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Runs the original desktop controller locally in Eva's existing Node runtime. */
final class DesktopBrowserRuntime {
 static java.lang.Process process;static BufferedWriter input;static final Map<String,CompletableFuture<JSONObject>> pending=new ConcurrentHashMap<>();
 static byte[] read(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();DesktopBrowserHost.pump(in,out);return out.toByteArray();}
 static JSONArray specs(Context c)throws Exception{try(InputStream in=c.getAssets().open("desktop-browser/tools.json")){return new JSONArray(new String(read(in),"UTF-8"));}}
 static void copy(Context c,String asset,File dest)throws Exception{String[] children=c.getAssets().list(asset);if(children!=null&&children.length>0){dest.mkdirs();for(String child:children)copy(c,asset+"/"+child,new File(dest,child));}else{dest.getParentFile().mkdirs();try(InputStream in=c.getAssets().open(asset)){Files.copy(in,dest.toPath(),StandardCopyOption.REPLACE_EXISTING);}}}
 static synchronized void start(Context c)throws Exception{if(process!=null&&process.isAlive())return;File root=new File(c.getFilesDir(),"alpine"),target=new File(root,"root/eva-browser");copy(c,"desktop-browser",target);String lib=c.getApplicationInfo().nativeLibraryDir;
 ProcessBuilder pb=new ProcessBuilder(lib+"/liboperit_proot.so","-0","-r",root.getAbsolutePath(),"-b","/dev","-b","/proc","-w","/root/eva-workspace","/usr/bin/node","/root/eva-browser/android-worker.mjs",DesktopBrowserHost.get(c).endpoint());pb.environment().put("EVA_ANDROID_ROOT",root.getAbsolutePath());pb.environment().put("PROOT_LOADER",lib+"/liboperit_loader.so");pb.environment().put("PROOT_TMP_DIR",new File(c.getFilesDir(),"tmp").getAbsolutePath());java.lang.Process child=LinuxRuntime.start(c,pb);process=child;input=new BufferedWriter(new OutputStreamWriter(child.getOutputStream(),"UTF-8"));
 new Thread(()->{try(BufferedReader reader=new BufferedReader(new InputStreamReader(child.getInputStream(),"UTF-8"))){String line;while((line=reader.readLine())!=null){JSONObject row=new JSONObject(line);CompletableFuture<JSONObject> f=pending.remove(row.optString("id"));if(f!=null){if(row.has("error"))f.completeExceptionally(new IOException(row.getString("error")));else f.complete(row.getJSONObject("result"));}}}catch(Exception ignored){}finally{for(CompletableFuture<JSONObject> f:pending.values())f.completeExceptionally(new IOException("浏览器控制器已停止"));pending.clear();}},"eva-browser-results").start();
 new Thread(()->{try(InputStream in=child.getErrorStream()){byte[] b=new byte[4096];while(in.read(b)!=-1){}}catch(Exception ignored){}},"eva-browser-errors").start();}
 static synchronized void write(JSONObject row)throws Exception{input.write(row.toString());input.newLine();input.flush();}
 static JSONObject execute(Context c,JSONObject p)throws Exception{KernelHost.guardTurn(p);BrowserOwnership.Lease lease=BrowserOwnership.claim(p);if(BrowserWindow.live==null)BrowserTools.execute(c,new JSONObject().put("action","show"),lease).get(8,TimeUnit.SECONDS);start(c);String id=KernelHost.turnKey(p)+":"+UUID.randomUUID();CompletableFuture<JSONObject> result=new CompletableFuture<>();pending.put(id,result);try{write(new JSONObject().put("id",id).put("session",p.getString("threadId")).put("tool",p.getString("tool")).put("args",p.getJSONObject("arguments")));long deadline=SystemClock.elapsedRealtime()+90000;while(true){if(SystemClock.elapsedRealtime()>deadline)throw new IOException("浏览器操作尚未确认，请先检查结果，不要重复执行");try{JSONObject out=result.get(200,TimeUnit.MILLISECONDS);BrowserOwnership.validate(lease,BrowserWindow.live);return out;}catch(TimeoutException wait){BrowserOwnership.validate(lease,BrowserWindow.live);}}}finally{pending.remove(id);if(!result.isDone())write(new JSONObject().put("cancel",id));}}
 static boolean handle(KernelHost host,JSONObject request){JSONObject p=request.optJSONObject("params");if(!"item/tool/call".equals(request.optString("method"))||p==null||!p.optString("tool").startsWith("browser_"))return false;host.work.execute(()->{JSONObject response=new JSONObject();try{JSONObject out=execute(host.context,p);response.put("success",true).put("contentItems",new JSONArray().put(new JSONObject().put("type","inputText").put("text",out.toString())));}catch(Exception e){try{response.put("success",false).put("contentItems",new JSONArray().put(new JSONObject().put("type","inputText").put("text",String.valueOf(e.getMessage()))));}catch(Exception ignored){}}try{host.write(new JSONObject().put("id",request.get("id")).put("result",response));}catch(Exception ignored){}});return true;}
}
